/*
 * A044958  Numbers with no two equally numerous base 9 digits.
 * https://oeis.org/A044958
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 54, u16 n <= 54, u32 n <= 54, u64 n <= 54, u128 n <= 54,
 *            big any n
 * Helpers:   valid_base9
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: Numbers with no two equally numerous base‑9 digits. */
/* Generated by checking each positive integer and selecting those
   whose base‑9 digit counts are all distinct (ignoring zeros). */

#include <stdlib.h>
#include <stddef.h>
#include <stdbool.h>
#include "../utils/valid_base9.h"

/* Static state to cache already found terms. */
static seq_t *cache          = NULL;
static size_t cache_size     = 0;
static size_t cache_cap      = 0;
static idx_t  last_tested    = 0;   /* largest integer examined so far */

/* Return the n‑th term of A044958. */
seq_t a( idx_t n )
{
    if ( n == 0 )
        return 0;   /* undefined for n = 0, but return 0 for safety */

    /* Ensure we have space for at least n terms. */
    if ( (size_t)n > cache_size && cache_cap < (size_t)n )
    {
        size_t new_cap = cache_cap ? cache_cap << 1 : 64;
        while ( new_cap < (size_t)n )
            new_cap <<= 1;
        seq_t *tmp = (seq_t *)realloc( cache, new_cap * sizeof( seq_t ) );
        cache = tmp;
        cache_cap = new_cap;
    }

    /* Return cached value if already computed. */
    if ( (size_t)n <= cache_size )
        return cache[(size_t)(n - 1)];

    /* Search for additional terms until we have n. */
    unsigned long long val = (unsigned long long)( last_tested + 1 );
    while ( cache_size < (size_t)n )
    {
        if ( valid_base9( val ) )
        {
            cache[cache_size++] = (seq_t)val;
            /* If we've reached the requested term, update and return. */
            if ( cache_size == (size_t)n )
            {
                last_tested = (idx_t)(val);
                return cache[(size_t)(n - 1)];
            }
        }
        ++val;
    }

    /* In normal execution we never reach here, but return the value. */
    last_tested = (idx_t)(val - 1);
    return cache[(size_t)(n - 1)];
}
